#!/bin/bash
# ============================================================
# TAT 直接部署命令 — checkin 路由修复
# 不依赖 GitHub，直接写入文件
# ============================================================
set -e
BACKEND_DIR="/www/xuewaiyu-backend"
cd "$BACKEND_DIR"

# 1. 备份 index.js
cp src/server/routes/index.js src/server/routes/index.js.bak.$(date +%Y%m%d_%H%M%S)

# 2. 写入 checkinController.js
mkdir -p src/server/controllers
echo "" | base64 -d > src/server/controllers/checkinController.js
echo "✓ checkinController.js"

# 3. 写入 checkin route
echo "" | base64 -d > src/server/routes/checkin.js
echo "✓ checkin.js"

# 4. 安全注册路由（Python 精确插入，不破坏文件）
echo "Registering routes..."
python3 -c "
import re
with open('src/server/routes/index.js', 'r') as f:
    content = f.read()

# 检查 checkin 路由
if \"require('./checkin')\" not in content:
    content = re.sub(r'(module\.exports\s*=)', \"app.use('/api/checkin', require('./checkin'));\n\\1\", content, count=1)
    print('checkin route registered')
else:
    print('checkin route already exists')

with open('src/server/routes/index.js', 'w') as f:
    f.write(content)
" 2>&1
echo "✓ Routes registered"

# 5. Prisma 同步
echo "Generating Prisma client..."
npx prisma generate 2>&1
echo "✓ Prisma client generated"

# 6. 重启 PM2
echo "Restarting PM2..."
pm2 restart xuewaiyu-backend --update-env
sleep 2
pm2 status

echo ""
echo "=== Deploy Complete ==="
echo "Checkin: POST/GET https://yandao.vip/api/checkin"